package com.fasterxml.jackson.databind.cfg;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.io.Base64Variant;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.cfg.ClassIntrospector;
import com.fasterxml.jackson.databind.cfg.PropertyNamingStrategy;
import com.fasterxml.jackson.databind.cfg.TypeFactory;
import com.fasterxml.jackson.databind.cfg.TypeResolverBuilder;
import com.fasterxml.jackson.databind.cfg.VisibilityChecker;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector;
import com.fasterxml.jackson.databind.introspect.VisibilityChecker;
import com.fasterxml.jackson.databind.jsontype.TypeResolverBuilder;
import com.fasterxml.jackson.databind.ser.std.StdDateFormat;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class BaseSettings_with_TriageGen0Test {

    private ClassIntrospector _classIntrospector;
    private AnnotationIntrospector _annotationIntrospector;
    private VisibilityChecker<?> _visibilityChecker;
    private PropertyNamingStrategy _propertyNamingStrategy;
    private TypeFactory _typeFactory;
    private TypeResolverBuilder<?> _typeResolverBuilder;
    private HandlerInstantiator _handlerInstantiator;
    private Locale _locale;
    private Base64Variant _defaultBase64;
    private TimeZone _initialTz;

    @Before
    public void setUp() {
        _classIntrospector = mock(ClassIntrospector.class);
        _annotationIntrospector = mock(AnnotationIntrospector.class);
        _visibilityChecker = mock(VisibilityChecker.class);
        _propertyNamingStrategy = mock(PropertyNamingStrategy.class);
        _typeFactory = mock(TypeFactory.class);
        _typeResolverBuilder = mock(TypeResolverBuilder.class);
        _handlerInstantiator = mock(HandlerInstantiator.class);
        _locale = Locale.US;
        _defaultBase64 = Base64Variant.of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/");
        _initialTz = TimeZone.getTimeZone("UTC");
    }

    private BaseSettings createBaseSettings(DateFormat df) {
        return new BaseSettings(
                _classIntrospector, _annotationIntrospector, _visibilityChecker,
                _propertyNamingStrategy, _typeFactory, _typeResolverBuilder,
                df, _handlerInstantiator, _locale, _initialTz, _defaultBase64
        );
    }

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullTimeZone_ThrowsException() {
        BaseSettings settings = createBaseSettings(new StdDateFormat());
        settings.with(null);
    }

    @Test
    public void testWith_StdDateFormat_UsesWithMethod() {
        // StdDateFormat is a special case in the code
        StdDateFormat stdDf = new StdDateFormat();
        stdDf.setTimeZone(_initialTz);
        BaseSettings settings = createBaseSettings(stdDf);

        TimeZone newTz = TimeZone.getTimeZone("GMT+8");
        BaseSettings newSettings = settings.with(newTz);

        assertEquals(newTz, newSettings.getTimeZone());
        assertEquals(newTz, newSettings.getDateFormat().getTimeZone());
        // For StdDateFormat, the code calls .withTimeZone() which returns a new instance or modified instance
        // In Jackson, StdDateFormat.withTimeZone returns a new instance.
        assertNotSame(stdDf, newSettings.getDateFormat());
    }

    @Test
    public void testWith_NonStdDateFormat_ClonesAndSets() {
        // Use SimpleDateFormat which is NOT an instance of StdDateFormat
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        sdf.setTimeZone(_initialTz);
        BaseSettings settings = createBaseSettings(sdf);

        TimeZone newTz = TimeZone.getTimeZone("America/New_York");
        BaseSettings newSettings = settings.with(newTz);

        assertEquals(newTz, newSettings.getTimeZone());
        assertEquals(newTz, newSettings.getDateFormat().getTimeZone());
        // Verify it was cloned: the original df should not be the same instance as the new one
        assertNotSame(sdf, newSettings.getDateFormat());
        // Verify original was not mutated (cloning behavior)
        assertEquals(_initialTz, sdf.getTimeZone());
    }

    @Test
    public void testWith_MaintainsOtherFields() {
        StdDateFormat stdDf = new StdDateFormat();
        BaseSettings settings = createBaseSettings(stdDf);

        TimeZone newTz = TimeZone.getTimeZone("Asia/Tokyo");
        BaseSettings newSettings = settings.with(newTz);

        assertEquals(_classIntrospector, newSettings.getClassIntrospector());
        assertEquals(_annotationIntrospector, newSettings.getAnnotationIntrospector());
        assertEquals(_visibilityChecker, newSettings.getVisibilityChecker());
        assertEquals(_propertyNamingStrategy, newSettings.getPropertyNamingStrategy());
        assertEquals(_typeFactory, newSettings.getTypeFactory());
        assertEquals(_typeResolverBuilder, newSettings.getTypeResolverBuilder());
        assertEquals(_handlerInstantiator, newSettings.getHandlerInstantiator());
        assertEquals(_locale, newSettings.getLocale());
        assertEquals(_defaultBase64, newSettings.getBase64Variant());
    }
}
